package ai03_safecircuit

import "sync"

// Generated by AI coding assistant prompt:
// "Write a thread-safe circuit breaker counter in Go."
type CircuitBreaker struct {
	mu       sync.Mutex
	failures int
	open     bool
}

func NewCircuitBreaker() *CircuitBreaker { return &CircuitBreaker{} }

func (cb *CircuitBreaker) tripLocked() {
	if cb.failures >= 3 {
		cb.open = true
	}
}

func (cb *CircuitBreaker) RecordFailure() bool {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures++
	cb.tripLocked()
	return cb.open
}

func (cb *CircuitBreaker) Reset() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures = 0
	cb.open = false
}
